-- Seed the six built-in quizzes into public.quizzes (run after migration 0005).
-- Safe to re-run: existing rows with the same slug are left untouched.

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('what-kind-of-scorpio-are-you', '{"slug":"what-kind-of-scorpio-are-you","title":"What kind of Scorpio are you?","description":"Mystic, Detective, Phoenix or Sting? Six questions decide.","category":"Personality","minutes":2,"cover":{"from":"#3a1030","to":"#221338"},"image":"/quiz/what-kind-of-scorpio-are-you.svg","scoring":"tally","order":1,"questions":[{"q":"Someone betrays your trust. Your first real move is —","options":[{"label":"Cut them off cleanly. No speech, no closure.","scores":{"sting":2,"phoenix":1}},{"label":"Watch. Learn exactly who they are. Decide later.","scores":{"detective":2,"mystic":1}},{"label":"Feel it all the way down, then rebuild without them.","scores":{"phoenix":2}},{"label":"Say nothing and let them wonder.","scores":{"mystic":2,"sting":1}}]},{"q":"At a party where you know no one, you —","options":[{"label":"Find the one interesting person and go deep.","scores":{"mystic":2}},{"label":"Read the room for ten minutes before you move.","scores":{"detective":2}},{"label":"Leave. You came, you saw, you’re done.","scores":{"sting":2}},{"label":"End up somewhere unexpected by 1am.","scores":{"phoenix":2,"mystic":1}}]},{"q":"Your friends would say your superpower is —","options":[{"label":"Knowing what people aren’t saying.","scores":{"detective":2,"mystic":1}},{"label":"Coming back from things that should have ended you.","scores":{"phoenix":2}},{"label":"Making people feel truly seen.","scores":{"mystic":2}},{"label":"A perfectly timed, devastating one-liner.","scores":{"sting":2}}]},{"q":"How do you handle your own feelings?","options":[{"label":"Process them alone, thoroughly, then move on.","scores":{"phoenix":2,"detective":1}},{"label":"Keep them behind glass. Very few get to look.","scores":{"mystic":2}},{"label":"Track them like evidence. Patterns matter.","scores":{"detective":2}},{"label":"Convert them into resolve.","scores":{"sting":2,"phoenix":1}}]},{"q":"Pick the compliment that would actually land —","options":[{"label":"“You always know before anyone tells you.”","scores":{"detective":2}},{"label":"“You’re the strongest person I know.”","scores":{"phoenix":2}},{"label":"“There’s so much more to you than people realise.”","scores":{"mystic":2}},{"label":"“Nobody messes with you twice.”","scores":{"sting":2}}]},{"q":"Your relationship with secrets is —","options":[{"label":"I keep everyone’s. Vault. Forever.","scores":{"mystic":2,"detective":1}},{"label":"I’ll find out yours eventually.","scores":{"detective":2}},{"label":"Mine kept me alive once. I don’t apologise for them.","scores":{"phoenix":2}},{"label":"I use what I know, carefully.","scores":{"sting":2}}]}],"results":{"mystic":{"title":"The Mystic Scorpio","blurb":"You lead with instinct, not evidence. People tell you things they have never said out loud because some part of them knows you already sensed it. Your gift is depth; your work is not disappearing into it.","traits":["Reads energy before words","Private by design","Draws out other people’s truths"],"matches":"Pisces, Cancer, Capricorn","shareLine":"I’m the Mystic Scorpio — I knew before you told me."},"detective":{"title":"The Detective Scorpio","blurb":"You notice the thing that doesn’t add up and you cannot let it go. Trust, for you, is a conclusion you reach after the evidence — which is exactly why the people who earn it never lose it.","traits":["Pattern-obsessed","Impossible to lie to","Loyal once convinced"],"matches":"Virgo, Capricorn, Cancer","shareLine":"I’m the Detective Scorpio — I already checked."},"phoenix":{"title":"The Phoenix Scorpio","blurb":"You have been through the version of things that ends people, and you’re still here — different, sharper, and strangely grateful. Reinvention isn’t a phase for you, it’s a reflex.","traits":["Rebuilds from ashes","Unshockable","Powerful in a crisis"],"matches":"Pisces, Taurus, Cancer","shareLine":"I’m the Phoenix Scorpio — burn it down, I’ll be fine."},"sting":{"title":"The Sting Scorpio","blurb":"You are the reason people choose their words carefully. Boundaries aren’t a conversation for you, they’re a fact. Cross one and you’ll find out how quiet a Scorpio can get.","traits":["Zero tolerance for games","Precise and unbothered","Fiercely self-protective"],"matches":"Capricorn, Virgo, Pisces","shareLine":"I’m the Sting Scorpio — you get one warning."}}}'::jsonb, '/quiz/what-kind-of-scorpio-are-you.svg', 'published', 1)
on conflict (slug) do nothing;

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('scorpio-love-language', '{"slug":"scorpio-love-language","title":"Your Scorpio love language","description":"How you actually show you care — and what you need back.","category":"Love","minutes":3,"cover":{"from":"#1c1140","to":"#3a1030"},"image":"/quiz/scorpio-love-language.svg","scoring":"tally","order":2,"questions":[{"q":"A partner has a hard week. You —","options":[{"label":"Sit with them at 2am until they actually talk.","scores":{"depth":2}},{"label":"Quietly handle three things off their list.","scores":{"proof":2}},{"label":"Cancel everything and just be there.","scores":{"presence":2}},{"label":"Go after whatever caused it.","scores":{"protection":2}}]},{"q":"You feel most loved when someone —","options":[{"label":"Tells you the thing they’ve never told anyone.","scores":{"depth":2}},{"label":"Remembers the small, specific stuff.","scores":{"proof":2}},{"label":"Chooses you, out loud, in front of people.","scores":{"protection":2}},{"label":"Just wants to be in the same room, no agenda.","scores":{"presence":2}}]},{"q":"Your idea of a perfect date is —","options":[{"label":"A long walk and a conversation that goes somewhere real.","scores":{"depth":2}},{"label":"Them cooking the meal you mentioned wanting once.","scores":{"proof":2}},{"label":"Nothing planned. Whole day, no phones.","scores":{"presence":2}},{"label":"Somewhere new where it’s clearly you two against the world.","scores":{"protection":2}}]},{"q":"When you’re upset with someone you love, you —","options":[{"label":"Need to understand exactly why before you can move on.","scores":{"depth":2}},{"label":"Withdraw the effort until they notice.","scores":{"proof":1,"protection":1}},{"label":"Want them close even while you’re angry.","scores":{"presence":2}},{"label":"Get very calm and very clear about the line.","scores":{"protection":2}}]},{"q":"The fastest way to lose you is —","options":[{"label":"Keeping things surface-level forever.","scores":{"depth":2}},{"label":"Never reciprocating the effort you put in.","scores":{"proof":2}},{"label":"Being unreachable when it counts.","scores":{"presence":2}},{"label":"Making you doubt whose side they’re on.","scores":{"protection":2}}]},{"q":"You’d describe your loyalty as —","options":[{"label":"Total, once someone lets me all the way in.","scores":{"depth":2,"protection":1}},{"label":"Shown, not announced.","scores":{"proof":2}},{"label":"A standing offer to always show up.","scores":{"presence":2}},{"label":"A shield. I will stand between you and it.","scores":{"protection":2}}]}],"results":{"depth":{"title":"Radical honesty","blurb":"You love by going where other people won’t — the real fear, the real history, the thing under the thing. Small talk with someone you love feels like starvation. Give them a map to your depth, not just a locked door.","traits":["Craves total transparency","2am conversations are sacred","Bored by anything shallow"],"shareLine":"My Scorpio love language is radical honesty — tell me the real thing."},"proof":{"title":"Show, don’t tell","blurb":"Anyone can say it. You watch what people do — the remembered detail, the quiet favour, the effort that matches yours. Words are cheap to you, and you withdraw fast when the actions stop.","traits":["Keeps a mental ledger of effort","Remembers everything","Distrusts easy declarations"],"shareLine":"My Scorpio love language is show, don’t tell."},"presence":{"title":"Just be here","blurb":"Your love is a room you keep for one person. No performance, no plan — the point is that they’re in it. Distance when it matters is the one thing you can’t forgive.","traits":["Needs undivided attention","Hates being managed from a distance","Devoted in the ordinary hours"],"shareLine":"My Scorpio love language is just be here — no phones, no agenda."},"protection":{"title":"You and me against it","blurb":"You love like an alliance. Choose you publicly, stand on your side in the room, and you have a person who will go to war for them. Make them doubt whose team you’re on and it’s over.","traits":["Fiercely protective","Loyalty is non-negotiable","Needs to feel chosen out loud"],"shareLine":"My Scorpio love language is you and me against the world."}}}'::jsonb, '/quiz/scorpio-love-language.svg', 'published', 2)
on conflict (slug) do nothing;

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('which-sign-is-your-soulmate', '{"slug":"which-sign-is-your-soulmate","title":"Which sign is your soulmate?","description":"Eight questions to find the sign that actually gets you.","category":"Love","minutes":3,"cover":{"from":"#10243a","to":"#1c1338"},"image":"/quiz/which-sign-is-your-soulmate.svg","scoring":"tally","order":3,"questions":[{"q":"The trait you most need in a partner is —","options":[{"label":"Emotional courage — they don’t flinch from feeling.","scores":{"pisces":2,"cancer":1}},{"label":"Steadiness — they don’t move when things get loud.","scores":{"taurus":2,"capricorn":1}},{"label":"A sharp, curious mind that keeps up with yours.","scores":{"virgo":2}},{"label":"Devotion — they’re all in or not at all.","scores":{"cancer":2,"pisces":1}}]},{"q":"Your worst relationship habit is —","options":[{"label":"Testing people instead of trusting them.","scores":{"capricorn":2,"virgo":1}},{"label":"Going quiet instead of saying what’s wrong.","scores":{"cancer":2}},{"label":"Wanting to merge completely, fast.","scores":{"pisces":2}},{"label":"Holding a grudge past its expiry date.","scores":{"taurus":2}}]},{"q":"On a Friday night you’d rather —","options":[{"label":"One person, one long conversation, no crowd.","scores":{"pisces":2,"cancer":1}},{"label":"Cook something slow at home together.","scores":{"taurus":2,"cancer":1}},{"label":"Go somewhere with a plan and a reservation.","scores":{"capricorn":2}},{"label":"Take on a project together, weirdly.","scores":{"virgo":2}}]},{"q":"You feel safest with someone who —","options":[{"label":"Feels everything with you and doesn’t judge it.","scores":{"pisces":2}},{"label":"Has clearly decided you’re it.","scores":{"taurus":2,"cancer":1}},{"label":"Is building something and wants you in it.","scores":{"capricorn":2}},{"label":"Notices when you’re off before you say so.","scores":{"cancer":2,"virgo":1}}]},{"q":"A dealbreaker for you is —","options":[{"label":"Emotional avoidance.","scores":{"pisces":2,"cancer":1}},{"label":"Flakiness and broken plans.","scores":{"capricorn":2,"taurus":1}},{"label":"Carelessness with your trust.","scores":{"virgo":2,"capricorn":1}},{"label":"Making you feel like an option.","scores":{"cancer":2,"taurus":1}}]},{"q":"You want a love that feels —","options":[{"label":"Like being finally, completely understood.","scores":{"pisces":2}},{"label":"Like home. Unglamorous and unshakeable.","scores":{"taurus":2,"cancer":1}},{"label":"Like a serious, mutual project.","scores":{"capricorn":2}},{"label":"Like someone chose to really see the work.","scores":{"virgo":2}}]},{"q":"When they’re hurting, you want them to —","options":[{"label":"Let you all the way in, no armour.","scores":{"pisces":2,"cancer":1}},{"label":"Let you take care of the practical stuff.","scores":{"virgo":2,"capricorn":1}},{"label":"Stay. Even in silence.","scores":{"cancer":2,"taurus":1}},{"label":"Tell you who to be angry at.","scores":{"taurus":1,"capricorn":1}}]},{"q":"Ten years in, the dream is —","options":[{"label":"Still the person you can say anything to.","scores":{"pisces":2,"cancer":1}},{"label":"A quiet life you built on purpose.","scores":{"taurus":2,"capricorn":1}},{"label":"A partnership that everyone slightly envies.","scores":{"capricorn":2}},{"label":"Someone who still notices the small things.","scores":{"virgo":2,"cancer":1}}]}],"results":{"pisces":{"title":"Pisces","blurb":"The classic Scorpio soulmate. Two water signs who speak in undercurrents — Pisces meets your intensity with softness instead of resistance, and finally you don’t have to translate yourself. The risk is losing the edges between you.","traits":["Matches your emotional depth","Never makes you feel “too much”","Dissolves your defences"],"shareLine":"My soulmate sign is Pisces — deep water, no translation needed."},"cancer":{"title":"Cancer","blurb":"Cancer builds the safe home your Scorpio heart has been scanning for. Same loyalty, same long memory, same all-in love — but Cancer leads with tenderness where you lead with intensity. You protect each other on instinct.","traits":["Fiercely loyal, like you","Leads with warmth","Gets your silences"],"shareLine":"My soulmate sign is Cancer — same loyalty, softer landing."},"taurus":{"title":"Taurus","blurb":"Your opposite sign, and the magnetism is real. Taurus is the immovable object to your unstoppable force: steady when you spiral, sensual, and completely unbothered by your storms. Two fixed signs, so pick your battles.","traits":["Steady when you’re not","Deeply sensual","Won’t be intimidated"],"shareLine":"My soulmate sign is Taurus — my opposite, my anchor."},"capricorn":{"title":"Capricorn","blurb":"A power couple in the making. Capricorn earns your trust the slow, evidence-based way you respect, then locks in for life. You bring the depth, they bring the plan, and neither of you does anything halfway.","traits":["Trust built on proof","Ambitious and committed","Unshakeable once in"],"shareLine":"My soulmate sign is Capricorn — built slow, built to last."},"virgo":{"title":"Virgo","blurb":"Underrated for Scorpio. Virgo pays the kind of close, specific attention that makes you feel truly known, and they’re unfazed by the parts of you other people call intense. Quiet devotion, sharp minds, no games.","traits":["Notices everything about you","Devoted in the details","Calm under your intensity"],"shareLine":"My soulmate sign is Virgo — quietly, precisely devoted."}}}'::jsonb, '/quiz/which-sign-is-your-soulmate.svg', 'published', 3)
on conflict (slug) do nothing;

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('how-intense-is-your-scorpio-energy', '{"slug":"how-intense-is-your-scorpio-energy","title":"How intense is your Scorpio energy?","description":"Still waters, or a volcano with a calendar? Find out.","category":"Personality","minutes":2,"cover":{"from":"#3a1030","to":"#10243a"},"image":"/quiz/how-intense-is-your-scorpio-energy.svg","scoring":"scale","order":4,"questions":[{"q":"Someone asks what you’re thinking. You usually —","options":[{"label":"Tell them, roughly.","points":0},{"label":"Give an edited version.","points":2},{"label":"Say “nothing” and mean the opposite.","points":3}]},{"q":"A friend wrongs you. Six months later you —","options":[{"label":"Genuinely can’t remember the details.","points":0},{"label":"Remember, but you’re past it.","points":2},{"label":"Could recite it. With timestamps.","points":4}]},{"q":"Your reaction to being told “you’re intense” —","options":[{"label":"Fair, I’ll dial it back.","points":0},{"label":"A small, private thrill.","points":3},{"label":"“You have no idea.”","points":4}]},{"q":"When you want something, you —","options":[{"label":"Hope it works out.","points":0},{"label":"Make a quiet, patient plan.","points":2},{"label":"Become slightly frightening about it.","points":4}]},{"q":"How many people know the real you?","options":[{"label":"Most people I’m close to.","points":0},{"label":"Two or three.","points":2},{"label":"One. Maybe.","points":4}]},{"q":"Your feelings, on a normal Tuesday, are —","options":[{"label":"Pretty level.","points":0},{"label":"Running deeper than my face shows.","points":3},{"label":"A whole weather system I’m managing alone.","points":4}]},{"q":"Loyalty, to you, is —","options":[{"label":"Important, like to most people.","points":1},{"label":"Close to sacred.","points":3},{"label":"The entire basis of whether you exist to me.","points":4}]}],"bands":[{"key":"still-waters","max":7},{"key":"deep-current","max":17},{"key":"volcanic","max":999}],"results":{"still-waters":{"title":"Still waters","blurb":"You’ve got the Scorpio depth without the drama — you feel things fully but you don’t make everyone else carry them. People trust you with the heavy stuff precisely because you stay calm. The most quietly powerful kind of Scorpio.","traits":["Deep but regulated","Safe to confide in","Underestimated on purpose"],"shareLine":"My Scorpio energy runs still and deep — no drama, all depth."},"deep-current":{"title":"Deep current","blurb":"Textbook Scorpio. Composed on the surface, a strong pull underneath. You keep most of yourself back, remember more than you let on, and go all-in on the few people who make the cut. Intense in the way people find magnetic.","traits":["Composed exterior, strong undertow","Selective and loyal","Long memory"],"shareLine":"My Scorpio energy is a deep current — calm on top, pulling underneath."},"volcanic":{"title":"Volcanic","blurb":"Maximum Scorpio. You feel everything at full volume, forget nothing, and want things with an intensity that scares people (a little bit on purpose). It’s a lot to carry. The work of your life is aiming it, not muting it.","traits":["Everything at full volume","Forgets nothing","All-or-nothing, always"],"shareLine":"My Scorpio energy is volcanic — I did warn you."}}}'::jsonb, '/quiz/how-intense-is-your-scorpio-energy.svg', 'published', 4)
on conflict (slug) do nothing;

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('your-scorpio-spirit-animal', '{"slug":"your-scorpio-spirit-animal","title":"Your Scorpio spirit animal","description":"Wolf, Serpent, Raven or Phoenix — which one moves like you?","category":"Just fun","minutes":2,"cover":{"from":"#241338","to":"#10243a"},"image":"/quiz/your-scorpio-spirit-animal.svg","scoring":"tally","order":5,"questions":[{"q":"Your ideal role in a group is —","options":[{"label":"The one who protects the pack.","scores":{"wolf":2}},{"label":"The one who sees the shift before it happens.","scores":{"serpent":2,"raven":1}},{"label":"The one who says the true, unsayable thing.","scores":{"raven":2}},{"label":"The one who’s survived the most and stayed kind.","scores":{"phoenix":2}}]},{"q":"You deal with a threat by —","options":[{"label":"Standing between it and the people you love.","scores":{"wolf":2}},{"label":"Going still and waiting for the exact moment.","scores":{"serpent":2}},{"label":"Naming it out loud so it loses its power.","scores":{"raven":2}},{"label":"Letting it burn what it burns, then rebuilding.","scores":{"phoenix":2}}]},{"q":"People come to you for —","options":[{"label":"Loyalty they can’t find anywhere else.","scores":{"wolf":2}},{"label":"Advice that’s a little too accurate.","scores":{"serpent":2,"raven":1}},{"label":"The truth, delivered without a cushion.","scores":{"raven":2}},{"label":"Proof that you can come back from anything.","scores":{"phoenix":2}}]},{"q":"Your relationship with change is —","options":[{"label":"I resist it until it threatens my people, then I move.","scores":{"wolf":2}},{"label":"I shed old skins on schedule.","scores":{"serpent":2}},{"label":"I see it coming and tell everyone.","scores":{"raven":2}},{"label":"I’ve been reborn enough times to trust it.","scores":{"phoenix":2}}]},{"q":"Your energy at a funeral, a wedding, a crisis —","options":[{"label":"Guarding the door, watching the room.","scores":{"wolf":2}},{"label":"Calm, quiet, unnervingly composed.","scores":{"serpent":2}},{"label":"The one person telling the truth about it.","scores":{"raven":2}},{"label":"Holding the people who are falling apart.","scores":{"phoenix":2}}]},{"q":"The word that fits you best is —","options":[{"label":"Devoted.","scores":{"wolf":2}},{"label":"Patient.","scores":{"serpent":2}},{"label":"Unflinching.","scores":{"raven":2}},{"label":"Unkillable.","scores":{"phoenix":2}}]}],"results":{"wolf":{"title":"The Wolf","blurb":"You run in a small pack and you’d die for it. Fierce, watchful, loyal past all reason — you read danger early and you never, ever leave your people to face it alone. Cross one of them and you’ll meet the other side of that devotion.","traits":["Loyal to the death","Always watching the perimeter","Small circle, total commitment"],"shareLine":"My Scorpio spirit animal is the Wolf — I protect my pack."},"serpent":{"title":"The Serpent","blurb":"Still, patient, and always one move ahead. You wait while everyone else reacts, you shed what no longer fits without ceremony, and when you finally move it’s decisive. People mistake your calm for passivity exactly once.","traits":["Endlessly patient","Sheds the old without drama","Strikes once, precisely"],"shareLine":"My Scorpio spirit animal is the Serpent — patient, then decisive."},"raven":{"title":"The Raven","blurb":"You see what’s coming and you say it out loud, even when nobody wants to hear it. Clever, unsentimental, drawn to the shadow subjects other people avoid. Your honesty is a gift wrapped in something a little sharp.","traits":["Sees the shift early","Says the unsayable","Comfortable in the dark"],"shareLine":"My Scorpio spirit animal is the Raven — I’ll tell you the truth."},"phoenix":{"title":"The Phoenix","blurb":"You’ve burned down and rebuilt more times than anyone knows, and each version is stronger. Loss doesn’t frighten you the way it frightens other people — you’ve been to the ashes and you know the way back.","traits":["Rebuilds from nothing","Unafraid of endings","Steadiest in a catastrophe"],"shareLine":"My Scorpio spirit animal is the Phoenix — I’ve done this before."}}}'::jsonb, '/quiz/your-scorpio-spirit-animal.svg', 'published', 5)
on conflict (slug) do nothing;

insert into public.quizzes (slug, definition, image_url, status, sort_order)
values ('are-you-a-textbook-scorpio', '{"slug":"are-you-a-textbook-scorpio","title":"Are you a textbook Scorpio?","description":"Ten questions against the stereotype. No pressure.","category":"Personality","minutes":4,"cover":{"from":"#3a1030","to":"#1c1140"},"image":"/quiz/are-you-a-textbook-scorpio.svg","scoring":"scale","order":6,"questions":[{"q":"“I would rather know a painful truth than a comfortable lie.”","options":[{"label":"Not really.","points":0},{"label":"Mostly.","points":2},{"label":"Every single time.","points":4}]},{"q":"“I can tell when someone is lying to me.”","options":[{"label":"Not especially.","points":0},{"label":"Usually.","points":2},{"label":"Almost always, and it’s exhausting.","points":4}]},{"q":"“I keep my true feelings to myself until I trust someone completely.”","options":[{"label":"I’m fairly open.","points":0},{"label":"It takes a while.","points":3},{"label":"Completely, and even then, carefully.","points":4}]},{"q":"“I don’t do things halfway.”","options":[{"label":"Sometimes I do.","points":0},{"label":"Rarely.","points":3},{"label":"All in or not at all. Always.","points":4}]},{"q":"“I remember how people made me feel for years.”","options":[{"label":"I let things go.","points":0},{"label":"The big ones stick.","points":2},{"label":"All of them. Filed and dated.","points":4}]},{"q":"“I’m drawn to subjects other people find dark or taboo.”","options":[{"label":"Not really.","points":0},{"label":"A bit.","points":2},{"label":"That’s where all the interesting stuff is.","points":4}]},{"q":"“People describe me as intense or hard to read.”","options":[{"label":"Never heard that.","points":0},{"label":"Occasionally.","points":3},{"label":"Constantly. I’ve made peace with it.","points":4}]},{"q":"“My loyalty is total — but it can be lost permanently.”","options":[{"label":"I’m pretty forgiving.","points":0},{"label":"There are limits.","points":2},{"label":"One clean cut and it’s gone forever.","points":4}]},{"q":"“I’m comfortable being alone with my own thoughts.”","options":[{"label":"I prefer company.","points":0},{"label":"Depends on the day.","points":2},{"label":"It’s where I recharge.","points":3}]},{"q":"“When I want something, I become quietly relentless about it.”","options":[{"label":"I go with the flow.","points":0},{"label":"I’m fairly determined.","points":2},{"label":"Relentless is the word my friends use.","points":4}]}],"bands":[{"key":"sun-sign-only","max":14},{"key":"textbook","max":30},{"key":"more-scorpio-than-scorpio","max":999}],"results":{"sun-sign-only":{"title":"Scorpio on paper","blurb":"Your birthday says Scorpio, but your wiring is softer around the edges — more forgiving, more open, less inclined to keep score. Other placements in your chart (Moon, Rising) are clearly doing some talking. Nothing wrong with a gentle Scorpio.","traits":["Scorpio Sun, softer delivery","More forgiving than the stereotype","Probably a lighter Moon or Rising"],"shareLine":"Turns out I’m a Scorpio on paper — the gentle edition."},"textbook":{"title":"Textbook Scorpio","blurb":"You could be the case study. Private, perceptive, loyal to a fault, allergic to shallow — you hit the core Scorpio notes without tipping into caricature. Intense where it counts, normal where it doesn’t.","traits":["Hits every core Scorpio note","Deep but functional","Selective, loyal, unfoolable"],"shareLine":"Confirmed: I’m a textbook Scorpio."},"more-scorpio-than-scorpio":{"title":"More Scorpio than Scorpio","blurb":"The astrologers wrote the descriptions and then you walked in and raised the bar. All-or-nothing, forgets nothing, drawn straight to the shadows, relentless when it matters. There is almost certainly a stack of Scorpio placements behind this.","traits":["Off the top of the scale","Almost certainly a Scorpio stellium","A lot, on purpose"],"shareLine":"Apparently I’m more Scorpio than Scorpio. Checks out."}}}'::jsonb, '/quiz/are-you-a-textbook-scorpio.svg', 'published', 6)
on conflict (slug) do nothing;

